  : '';

return [{ json: { ...config, resolveKey, resolveType, resolverUrl, queryCompanyId, _msgData: msgData } }];

const base = $('🔍 Preparar Resolución').item.json;
let resolved = {};
try {
  const r = $('🏢 Resolver Empresa (G54)').item.json;
  if (r && r.company_id && !r.error && !r.message) resolved = r.data || r;
} catch(e) {}

const company_id = String(base.queryCompanyId || resolved.company_id || base.G54_COMPANY_ID || '1');
const fb_access_token = resolved.fb_access_token || '';

return [{ json: {
  G54_BASE_URL: base.G54_BASE_URL,
  G54_N8N_TOKEN: base.G54_N8N_TOKEN,
  G54_AGENT_TOKEN: base.G54_AGENT_TOKEN,
  G54_COMPANY_ID: company_id,
  FB_ACCESS_TOKEN: fb_access_token
} }];

// Determine which extractor has the message (WA or Social)
