const telefono = msgData?.telefono || '';
const canal = msgData?.canal || 'whatsapp';
const nombreContacto = msgData?.nombreContacto || '';
const usuarioId = msgData?.usuarioId || '';
const messageId = msgData?.messageId || '';

// Empresa
const empresaRaw = $('🏢 Obtener Empresa G54').item.json;
const empresa = empresaRaw?.data || empresaRaw || {};
const empresa_nombre = empresa.name || 'Empresa';
const empresa_descripcion = empresa.description || '';
const empresa_ciudad = empresa.base_city || '';
const empresa_web = empresa.website || '';
const emailsVendedor = (empresa.emails || []).join(',') || '';

// WA Config (todo desde G54)
const waConfigRaw = $('⚙️ Obtener WA Config G54').item.json;
const waConfig = waConfigRaw?.data || {};

const nombre_agente = waConfig.agent_name || 'Agente';
const wa_access_token = waConfig.wa_access_token || '';
const phone_number_id = waConfig.phone_number_id || '';
const bienvenida = waConfig.welcome_message || `Hola 👋 Soy ${nombre_agente}, el asistente de ${empresa_nombre}. ¿En qué te puedo ayudar?`;
const instruccionesIA = waConfig.ia_instructions || '';
const promptTemplate = waConfig.system_prompt || `Eres {{AGENTE}}, asistente virtual de {{EMPRESA}}. Ayuda al cliente a conocer los productos y servicios disponibles. Catálogo:\n{{CATALOGO}}\n{{INSTRUCCIONES}}`;
const followup24 = waConfig.followup_24h || '';
const followup72 = waConfig.followup_72h || '';

// Productos
const productosRaw = $('📦 Obtener Productos G54').item.json;
const productos = productosRaw?.data || [];
const catalogoProductos = productos.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  const kw = (p.keywords || []).join(', ');
  return `• ${nombre}: ${desc}${kw ? ' [' + kw + ']' : ''}`;
}).filter(l => l.length > 3).join('\n');

// Lead existente
const leadRaw = $('📋 Buscar Lead Existente').item.json;
const leads = leadRaw?.data || [];
const leadExistente = leads[0] || null;
const leadId = leadExistente?.id || null;
const leadDatos = leadExistente?.datos || {};
const estado = leadExistente?.estado || 'Nuevo';
const historial = leadExistente?.historial || '';
const esNuevo = !leadId;

// datos_actualizados is a free object — the prompt defines what to collect
// We carry over whatever was stored previously and let AI merge
const datosRecolectados = typeof leadDatos === 'object' ? leadDatos : {};

// Build prompt — replace placeholders
const promptSistema = promptTemplate
  .replace(/\{\{AGENTE\}\}/g, nombre_agente)
  .replace(/\{\{EMPRESA\}\}/g, empresa_nombre)
  .replace(/\{\{CATALOGO\}\}/g, catalogoProductos || '(sin catálogo disponible)')
  .replace(/\{\{INSTRUCCIONES\}\}/g, instruccionesIA ? 'Instrucciones adicionales:\n' + instruccionesIA : '')
  .trim();

// Hora local (Miami UTC-4)
const h = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = h >= 6 && h < 12 ? 'buenos días' : h >= 12 && h < 19 ? 'buenas tardes' : 'buenas noches';

return [{ json: {
  // Message
  texto,
  telefono,
  canal,
  nombreContacto,
  usuarioId,
  messageId,
  // Context
  promptSistema,
  nombre_agente,
  empresa_nombre,
  empresa_descripcion,
  empresa_ciudad,
  empresa_web,
  emailsVendedor,
  bienvenida,
  followup24,
  followup72,
  catalogoProductos,
  // WA credentials (from G54 config)
  wa_access_token,
  phone_number_id,
  // Lead
  leadId,
  estado,
  historial,
  datosRecolectados,
  esNuevo,
  saludoHora
} }];

