    leadId: lead.id,
    telefono,
    nombre: lead.name || '',
    tipoFollowup,
    estado: lead.estado || '',
    mensajeFollowup: tipoFollowup === '24h' ? followup24 : followup72,
    wa_access_token,
    phone_number_id
  } });
}

return results.length ? results : [{ json: { skip: true } }];

