const ctx = $('🔧 Preparar Contexto IA').item.json;
const nombre = ctx.nombre_agente || 'el agente';
const empresa = ctx.empresa_nombre || 'nosotros';

return [{ json: {
  choices: [{
    message: {
      content: JSON.stringify({
        mensaje: `Hola, gracias por contactarnos. En este momento estamos experimentando un inconveniente técnico. Un representante de ${empresa} se pondrá en contacto contigo pronto. Disculpa las molestias.`,
        datos_actualizados: ctx.datosRecolectados || {},
        clasificacion: 'frio',
        todos_recolectados: false,
        resumen_lead: ''
      })
    }
  }]
} }];

// Accept output from Groq, Gemini (both OpenAI-compat) or emergency fallback
const raw = $input.item.json;
const content = raw.choices?.[0]?.message?.content || '{}';

let result;
try { result = JSON.parse(content); }
catch(e) {
  result = {
    mensaje: 'Gracias por tu mensaje. Te responderemos pronto.',
    datos_actualizados: {},
    clasificacion: 'frio',
    todos_recolectados: false,
    resumen_lead: ''
  };
}

const ctx = $('🔧 Preparar Contexto IA').item.json;
const datosAnt = ctx.datosRecolectados || {};
const datosNuevos = result.datos_actualizados || {};

// Merge: new values override old, but only if non-empty/non-null
const clean = v => (v === null || v === undefined || v === '' || v === 'desconocido' || v === 'null') ? null : v;
const datosMerged = { ...datosAnt };
for (const [k, v] of Object.entries(datosNuevos)) {
  const cleaned = clean(v);
  if (cleaned !== null) datosMerged[k] = cleaned;
}

// Estado válidos en G54
const clasificacion = (result.clasificacion || 'frio').toLowerCase();
let nuevoEstado = ctx.estado || 'Nuevo';
if (clasificacion === 'caliente') nuevoEstado = 'Vendedor notificado';
else if (clasificacion === 'tibio') nuevoEstado = 'Calificado';
else if (nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

const ts = new Date().toISOString();
const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '') +
  `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${result.mensaje || ''}`;

const mensaje = result.mensaje || '';

return [{ json: {
  ...ctx,
  mensaje,
  datosRecolectados: datosMerged,
  todos_recolectados: result.todos_recolectados === true,
  clasificacion,
  resumenLead: result.resumen_lead || '',
  nuevoEstado,
  nuevoHistorial
} }];

