const leadsRaw = $('📋 Obtener Leads Sin Respuesta').item.json;
const leads = leadsRaw?.data || leadsRaw?.records || [];

let waConfigRaw = {};
try { waConfigRaw = $('⚙️ Obtener WA Config Follow-up').item?.json || {}; } catch(e) {}
const waConfig = waConfigRaw?.data || {};

const followup24 = waConfig.followup_24h || 'Hola 👋 ¿Sigues necesitando ayuda? Aquí estamos para asistirte.';
const followup72 = waConfig.followup_72h || 'Seguimos disponibles cuando lo necesites 👍';
const wa_access_token = waConfig.wa_access_token || '';
const phone_number_id = waConfig.phone_number_id || '';

const now = new Date();
const results = [];

for (const lead of leads) {
  const ultimaActividad = new Date(lead.ultima_actividad || lead.created_at || 0);
  const horasDiff = (now - ultimaActividad) / (1000 * 60 * 60);
  let tipoFollowup = null;
  if (horasDiff >= 72) tipoFollowup = '72h';
  else if (horasDiff >= 24) tipoFollowup = '24h';
  if (!tipoFollowup) continue;

  const telefono = (lead.phone || '').replace(/^\+/, '');
  if (!telefono || telefono.startsWith('fbig_')) continue;

  results.push({ json: {
    leadId: lead.id,
    telefono,
    nombre: lead.name || '',
    tipoFollowup,
    estado: lead.estado || '',
    mensajeFollowup: tipoFollowup === '24h' ? followup24 : followup72,
    wa_access_token,
    phone_number_id
  } });
}

return results.length ? results : [{ json: { skip: true } }];
